/**
 * Parses the value of an HTTP Retry-After header into a number of
 * seconds to wait before retrying.
 */
export function parseRetryAfterHeader(value: string): number {
  const trimmed = value.trim();

  if (trimmed.length === 0) {
    return 0;
  }

  // Retry-After can be given as a plain integer number of seconds.
  if (/^\d+$/.test(trimmed)) {
    return parseInt(trimmed, 10);
  }

  // Otherwise it should be an HTTP-date (RFC 7231), e.g.
  // "Wed, 21 Oct 2026 07:28:00 GMT".
  const dateMs = Date.parse(trimmed);
  if (Number.isNaN(dateMs)) {
    throw new Error(`invalid Retry-After value: "${value}"`);
  }

  const deltaMs = dateMs - Date.now();
  const deltaSeconds = Math.ceil(deltaMs / 1000);

  return deltaSeconds > 0 ? deltaSeconds : 0;
}
